.trackCommentPanel .commentAvatar{width:34px!important;height:34px!important;flex-basis:34px!important;background:linear-gradient(145deg,rgba(255,213,31,.20),rgba(255,255,255,.08))!important;color:#ffd51f!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.08)!important}
.trackCommentActions{display:flex!important;gap:14px!important;margin:0!important;padding-left:42px!important}
