.trackCommentReplies{display:grid!important;gap:8px!important;margin:5px 0 0 42px!important}
.trackCommentReply{display:grid!important;grid-template-columns:22px minmax(0,1fr)!important;gap:7px!important;align-items:start!important}
.trackCommentReply>span{display:grid!important;place-items:center!important;width:22px!important;height:22px!important;border-radius:50%!important;background:rgba(255,213,31,.12)!important;color:#ffd51f!important;font-size:10px!important;font-weight:950!important}
.trackCommentReply strong{font-size:12px!important;color:rgba(255,255,255,.84)!important}
.trackCommentReply small{margin-left:6px!important;color:rgba(255,255,255,.42)!important;font-size:10px!important}
.trackCommentReply p{margin:2px 0 0!important;padding:0!important;font-size:12px!important;line-height:1.35!important;color:rgba(255,255,255,.62)!important}
.trackCommentReplyBox{display:grid!important;gap:7px!important;margin:7px 0 0 42px!important}
.trackCommentReplyBox.hidden{display:none!important}
.trackCommentReplyBox textarea{min-height:42px!important;border:0!important;border-bottom:1px solid rgba(255,255,255,.12)!important;background:rgba(255,255,255,.025)!important;color:var(--text)!important;padding:8px 10px!important;resize:vertical!important}
.trackCommentReplyBox div{display:flex!important;gap:8px!important;justify-content:flex-end!important}
