.trackCommentComposer .trackCommentIdentity>div{display:none!important}
.trackCommentTextareaWrap{position:relative!important;min-width:0!important}
.trackCommentPanel .commentForm textarea{border:0!important;border-bottom:1px solid rgba(255,255,255,.12)!important;border-radius:0!important;background:rgba(255,255,255,.025)!important;color:var(--text)!important;box-shadow:none!important;transition:border-color .18s ease,background .18s ease}
