.muzeChatHeader>div{display:flex;align-items:center;gap:13px}.muzeChatHeader h3{margin:0 0 4px;font-size:22px}.muzeChatHeader p{margin:0;color:rgba(255,255,255,.62);font-size:13px;font-weight:650}
